"""Writes tools/stats/cases_t8.txt: poisstat, friedman, canoncorr, nbinfit, gevfit, gpfit."""
import os
here = os.path.dirname(os.path.abspath(__file__))
PRE = ("fr=[x(1:12)' y(1:12)' x(13:24)']+repmat([0 0.5 1],12,1); Xa=[x(1:30)' y(1:30)' x(31:60)']; Ya=[x(61:90)'+0.5*x(1:30)' y(61:90)'-0.3*y(1:30)']; "
       "cnt=[0 1 3 2 5 0 7 4 2 9 1 3 6 2 4 8 0 1 5 3 2 4 6 1 0 2 3 5 7 2]; xg=abs(x(1:50))+0.2; ")
L = ["# generated by make_t8_cases.py"]
def add(cs, fmt):
    for c in cs: L.append(fmt.replace("{c}", c))
add(["poisstat(3)", "poisstat([1 2 5])", "poisstat([1;2;5])", "poisstat([2 3;4 5])", "poisstat(0)", "poisstat(-1)", "poisstat(single(3))", "poisstat()", "poisstat('a')", "poisstat(Inf)", "poisstat(NaN)"], "[a_,b_] = {c}; r = {a_,b_};")
add(["canoncorr(Xa,Ya)", "canoncorr(Xa(:,1:2),Ya)", "canoncorr(Xa,Ya(:,1))", "canoncorr(Xa(:,1),Ya(:,1))", "canoncorr(Xa(1:5,:),Ya(1:5,:))", "canoncorr(Xa,Ya(1:10,:))", "canoncorr(Xa,[Ya Ya(:,1)])", "canoncorr([Xa Xa(:,1)],Ya)", "canoncorr(single(Xa),single(Ya))", "canoncorr(Xa)", "canoncorr(Xa,Ya+NaN)", "canoncorr(Xa,[Ya;Ya(1,:)])"], "[A_,B_,r_,U_,V_,st_] = {c}; r = {A_,B_,r_,U_,V_,st_.Wilks,st_.df1,st_.df2,st_.F,st_.pF,st_.chisq,st_.pChisq,st_.dfe};")
add(["nbinfit(cnt)", "nbinfit(cnt')", "nbinfit(cnt,0.1)", "nbinfit([cnt 100])", "nbinfit([1 1 1])", "nbinfit(-cnt)", "nbinfit(cnt+0.5)", "nbinfit(single(cnt))", "nbinfit(cnt(1:5))", "nbinfit([0 0 0 1])", "nbinfit(cnt,[],statset('TolX',1e-3))", "nbinfit([cnt;cnt])", "nbinfit([])", "nbinfit(cnt*3)"], "[a_,b_] = {c}; r = {a_,b_};")
add(["gevfit(xg)", "gevfit(xg')", "gevfit(xg,0.1)", "gevfit(-xg)", "gevfit(xg(1:10))", "gevfit(xg*5)", "gevfit([xg;xg])", "gevfit(xg,[],statset('TolX',1e-3))", "gevfit(single(xg))", "gevfit([1 1 1])", "gevfit(x(1:50))", "gevfit(xg.^2)", "gevfit([xg NaN])", "gevfit([])"], "[a_,b_] = {c}; r = {a_,b_};")
add(["gpfit(xg)", "gpfit(xg')", "gpfit(xg,0.1)", "gpfit(xg*5)", "gpfit(xg(1:10))", "gpfit(-xg)", "gpfit(xg,[],statset('TolX',1e-3))", "gpfit(single(xg))", "gpfit([1 1 1])", "gpfit(xg.^2)", "gpfit([xg NaN])", "gpfit([])", "gpfit(xg-0.2)"], "[a_,b_] = {c}; r = {a_,b_};")
L = [L[0]] + [PRE + l for l in L[1:]]
with open(os.path.join(here, "cases_t8.txt"), "w", encoding="utf-8", newline="\n") as f:
    f.write("\n".join(L) + "\n")
print(len(L))
